        // ================================================================
        // --- samouczek interaktywny (screens/TutorialOverlay.kt)
        // Blok dopisany na końcu tabeli celowo: format "klucz" to t("pl", "en").
        // ================================================================
        "tut_step" to t("Samouczek %d/%d", "Tutorial %d/%d"),
        "tut_skip" to t("Pomiń samouczek", "Skip tutorial"),
        "tut_next" to t("Dalej", "Next"),
        "tut_go" to t("Do boju!", "To battle!"),
        "tut_melee_t" to t("Wyszkol pałkarza", "Train a Clubman"),
        "tut_melee" to t("Dotknij podświetlonego przycisku. Jednostka kosztuje złoto i po chwili rusza na wroga. Bitwa na ciebie poczeka.", "Tap the highlighted button. Units cost gold and march on the enemy once trained. The battle will wait for you."),
        "tut_income_t" to t("Złoto i teren", "Gold and territory"),
        "tut_income" to t("Złoto wpływa samo. Im dalej twoje wojsko odepchnie wroga, tym więcej terenu kontrolujesz i tym szybciej rośnie przychód.", "Gold flows in by itself. The further your army pushes the enemy back, the more territory you hold and the faster your income grows."),
        "tut_ranged_t" to t("Wsparcie z dystansu", "Ranged support"),
        "tut_ranged" to t("Wyszkol procarza. Strzela zza pleców pałkarzy: piechota z przodu, strzelcy z tyłu to najlepszy oddział.", "Train a Slinger. It shoots from behind your Clubmen: melee in front, ranged behind is the best squad."),
        "tut_kill_t" to t("Pierwszy pokonany wróg!", "First enemy down!"),
        "tut_kill" to t("Za każdego pokonanego wroga dostajesz złoto i doświadczenie (XP). XP wypełnia ten pasek i powoli rośnie też z czasem.", "Every enemy you defeat gives you gold and experience (XP). XP fills this bar and also grows slowly over time."),
        "tut_evolve_t" to t("Nowa epoka", "A new era"),
        "tut_evolve_wait" to t("Pasek XP jest prawie pełny. Gdy się zapełni, przycisk Awans zaświeci się na złoto.", "The XP bar is almost full. When it fills up, the Evolve button lights up gold."),
        "tut_evolve" to t("Naciśnij Awans! Wejdziesz w kolejną epokę: silniejsze jednostki, wieże i mocniejsza baza.", "Press Evolve! You enter the next era: stronger units, turrets and a tougher base."),
        "tut_doctrine_t" to t("Wybierz doktrynę", "Pick a doctrine"),
        "tut_doctrine" to t("Każdy awans daje wybór jednej z trzech doktryn: stałej premii do końca bitwy. Wybierz tę, która pasuje do twojego stylu.", "Every new era lets you pick one of three doctrines: a permanent bonus for the rest of the battle. Choose the one that fits your style."),
        "tut_turret_t" to t("Wieże obronne", "Defense turrets"),
        "tut_turret_open" to t("Otwórz panel wież. Wieża stoi przy bazie i sama ostrzeliwuje wrogów, którzy podejdą za blisko.", "Open the turret panel. Turrets stand by your base and shoot any enemy that comes too close."),
        "tut_turret_buy" to t("Kup pierwszą wieżę w wolnym slocie. Po awansie epoki możesz ją ulepszyć.", "Buy your first turret in a free slot. After a new era you can upgrade it."),
        "tut_barrage_t" to t("Ostrzał!", "Barrage!"),
        "tut_barrage" to t("Wrogowie zbili się w grupę. Użyj ostrzału: pociski spadną na pole przed twoją bazą. Potem zdolność musi się odnowić.", "The enemies are bunched up. Use the barrage: projectiles rain on the field in front of your base. Then the ability needs to recharge."),
        "tut_camera_t" to t("Rozejrzyj się", "Look around"),
        "tut_camera" to t("Przeciągnij palcem po polu bitwy, aby przesunąć widok, albo dotknij minimapy, aby skoczyć w wybrane miejsce.", "Drag across the battlefield to move the camera, or tap the minimap to jump to any spot."),
        "tut_done_t" to t("Gotowe, dowódco!", "Well done, commander!"),
        "tut_done" to t("Znasz podstawy. Zniszcz wrogą bazę po prawej stronie, zanim wróg zniszczy twoją.", "You know the basics. Destroy the enemy base on the right before the enemy destroys yours."),
        // --- koniec bloku samouczka
    )
}
